-- O nível atual do bairro é o da avaliação mais recente (mantém o que a
-- API já tiver registrado depois desta carga).
UPDATE BAIRRO B
   SET NIVEL_RISCO = (SELECT A.NIVEL
                        FROM AVALIACAO_RISCO A
                       WHERE A.BAIRRO_ID = B.ID
                       ORDER BY A.CRIADA_EM DESC, A.ID DESC
                       FETCH FIRST 1 ROW ONLY)
 WHERE EXISTS (SELECT 1 FROM AVALIACAO_RISCO A WHERE A.BAIRRO_ID = B.ID);

COMMIT;

-- Conferência da carga
SELECT 'BAIRRO' AS TABELA, COUNT(*) AS LINHAS FROM BAIRRO
UNION ALL SELECT 'USUARIO', COUNT(*) FROM USUARIO
UNION ALL SELECT 'DISPOSITIVO', COUNT(*) FROM DISPOSITIVO
UNION ALL SELECT 'AVALIACAO_RISCO', COUNT(*) FROM AVALIACAO_RISCO
UNION ALL SELECT 'LEITURA', COUNT(*) FROM LEITURA;
